for (const [english, map] of Object.entries(MORE)) {
  (Object.keys(map) as Exclude<DocLang, "en">[]).forEach((lang) => {
    const value = map[lang];
    if (value) PACKS[lang][english] = value;
  });
}

export function t(lang: DocLang, english: string): string {
  const raw = lang === "en" ? english : PACKS[lang]?.[english] ?? english;
  return withCurrency(raw, lang);
}
